18: static int _get_vsn(struct cmd_context *cmd, uint16_t *version_int)
19: {
20: 	const char *atversion = arg_str_value(cmd, atversion_ARG, LVM_VERSION);
21: 	unsigned int major, minor, patchlevel;
22: 
23: 	if (sscanf(atversion, "%u.%u.%u", &major, &minor, &patchlevel) != 3) {
24: 		log_error("Incorrect version format.");
25: 		return 0;
26: 	}
27: 
28: 	*version_int = vsn(major, minor, patchlevel);
29: 	return 1;
30: }
