32: static int _do_def_check(struct config_def_tree_spec *spec,
33: 			 struct dm_config_tree *cft,
34: 			 struct cft_check_handle **cft_check_handle)
35: {
36: 	struct cft_check_handle *handle;
37: 
38: 	if (!(handle = get_config_tree_check_handle(spec->cmd, cft)))
39: 		return 0;
40: 
41: 	handle->force_check = 1;
42: 	handle->suppress_messages = 1;
43: 
44: 	if (spec->type == CFG_DEF_TREE_DIFF) {
45: 		if (!handle->check_diff)
46: 			handle->skip_if_checked = 0;
47: 		handle->check_diff = 1;
48: 	} else {
49: 		handle->skip_if_checked = 1;
50: 		handle->check_diff = 0;
51: 	}
52: 
53: 	config_def_check(handle);
54: 	*cft_check_handle = handle;
55: 
56: 	return 1;
57: }
