59: static int _merge_config_cascade(struct cmd_context *cmd, struct dm_config_tree *cft_cascaded,
60: 				 struct dm_config_tree **cft_merged)
61: {
62: 	if (!cft_cascaded)
63: 		return 1;
64: 
65: 	if (!*cft_merged && !(*cft_merged = config_open(CONFIG_MERGED_FILES, NULL, 0)))
66: 		return_0;
67: 
68: 	if (!_merge_config_cascade(cmd, cft_cascaded->cascade, cft_merged))
69: 		return_0;
70: 
71: 	return merge_config_tree(cmd, *cft_merged, cft_cascaded, CONFIG_MERGE_TYPE_RAW);
72: }
