88: int dumpconfig(struct cmd_context *cmd, int argc, char **argv)
89: {
90: 	const char *file = arg_str_value(cmd, file_ARG, NULL);
91: 	const char *type = arg_str_value(cmd, configtype_ARG, "current");
92: 	struct config_def_tree_spec tree_spec = {0};
93: 	struct dm_config_tree *cft = NULL;
94: 	struct cft_check_handle *cft_check_handle = NULL;
95: 	struct profile *profile = NULL;
96: 	int r = ECMD_PROCESSED;
97: 
98: 	tree_spec.cmd = cmd;
99: 
100: 	if (arg_count(cmd, configtype_ARG) && arg_count(cmd, validate_ARG)) {
101: 		log_error("Only one of --type and --validate permitted.");
102: 		return EINVALID_CMD_LINE;
103: 	}
104: 
105: 	if (arg_count(cmd, atversion_ARG) && !arg_count(cmd, configtype_ARG)) {
106: 		log_error("--atversion requires --type");
107: 		return EINVALID_CMD_LINE;
108: 	}
109: 
110: 	if (arg_count(cmd, ignoreadvanced_ARG))
111: 		tree_spec.ignoreadvanced = 1;
112: 
113: 	if (arg_count(cmd, ignoreunsupported_ARG))
114: 		tree_spec.ignoreunsupported = 1;
115: 
116: 	if (arg_count(cmd, ignorelocal_ARG))
117: 		tree_spec.ignorelocal = 1;
118: 
119: 	if (!strcmp(type, "current")) {
120: 		if (arg_count(cmd, atversion_ARG)) {
121: 			log_error("--atversion has no effect with --type current");
122: 			return EINVALID_CMD_LINE;
123: 		}
124: 
125: 		if ((tree_spec.ignoreadvanced || tree_spec.ignoreunsupported)) {
126: 			log_error("--ignoreadvanced and --ignoreunsupported has "
127: 				  "no effect with --type current");
128: 			return EINVALID_CMD_LINE;
129: 		}
130: 	} else if (arg_count(cmd, mergedconfig_ARG)) {
131: 		log_error("--mergedconfig has no effect without --type current");
132: 		return EINVALID_CMD_LINE;
133: 	}
134: 
135: 	if (!_get_vsn(cmd, &tree_spec.version))
136: 		return EINVALID_CMD_LINE;
137: 
138: 	/*
139: 	 * The profile specified by --profile cmd arg is like --commandprofile,
140: 	 * but it is used just for dumping the profile content and not for
141: 	 * application.
142: 	 */
143: 	if (arg_count(cmd, profile_ARG) &&
144: 	    (!(profile = add_profile(cmd, arg_str_value(cmd, profile_ARG, NULL), CONFIG_PROFILE_COMMAND)) ||
145: 	    !override_config_tree_from_profile(cmd, profile))) {
146: 		log_error("Failed to load profile %s.", arg_str_value(cmd, profile_ARG, NULL));
147: 		return ECMD_FAILED;
148: 	}
149: 
150: 	/*
151: 	 * Set the 'cft' to work with based on whether we need the plain
152: 	 * config tree or merged config tree cascade if --mergedconfig is used.
153: 	 */
154: 	if (arg_count(cmd, mergedconfig_ARG) && cmd->cft->cascade) {
155: 		if (!_merge_config_cascade(cmd, cmd->cft, &cft)) {
156: 			log_error("Failed to merge configuration.");
157: 			r = ECMD_FAILED;
158: 			goto out;
159: 		}
160: 	} else
161: 		cft = cmd->cft;
162: 
163: 	if (arg_count(cmd, validate_ARG)) {
164: 		if (_config_validate(cmd, cft)) {
165: 			log_print("LVM configuration valid.");
166: 			goto out;
167: 		} else {
168: 			log_error("LVM configuration invalid.");
169: 			r = ECMD_FAILED;
170: 			goto out;
171: 		}
172: 	}
173: 
174: 	if (!strcmp(type, "current")) {
175: 		tree_spec.type = CFG_DEF_TREE_CURRENT;
176: 		if (!_do_def_check(&tree_spec, cft, &cft_check_handle)) {
177: 			r = ECMD_FAILED;
178: 			goto_out;
179: 		}
180: 	}
181: 	else if (!strcmp(type, "missing")) {
182: 		tree_spec.type = CFG_DEF_TREE_MISSING;
183: 		if (!_do_def_check(&tree_spec, cft, &cft_check_handle)) {
184: 			r = ECMD_FAILED;
185: 			goto_out;
186: 		}
187: 	}
188: 	else if (!strcmp(type, "default")) {
189: 		tree_spec.type = CFG_DEF_TREE_DEFAULT;
190: 		/* default type does not require check status */
191: 	}
192: 	else if (!strcmp(type, "diff")) {
193: 		tree_spec.type = CFG_DEF_TREE_DIFF;
194: 		if (!_do_def_check(&tree_spec, cft, &cft_check_handle)) {
195: 			r = ECMD_FAILED;
196: 			goto_out;
197: 		}
198: 	}
